export function proposalCompact(s,r,label){
const organisation={federated:'föderierte Arbeitsgruppen',central:'eine zentrale Redaktion',autonomous:'autonome Bandredaktionen'}[s.org];
const host={academy:'Der gemeinsame Akademieträger übernimmt Betrieb und Nachfolge über einzelne Arbeitsstellen hinweg.',uni:'Die federführende Universität übernimmt den Git-Betrieb; Partnerzugang und Übergabe werden in der Trägervereinbarung geregelt.',external:'Ein externer Dienst übernimmt die technische Bereitstellung; der Verbund verantwortet Verträge, Zugriffe und den Ausstieg.'}[s.host];
const repo={hybrid:'Bereichsrepos halten fachlich zusammenhängende Arbeit zusammen; ein Standards-Repo verbindet Schema, IDs und Regeln.',mono:'Ein gemeinsames Arbeitsrepo verbindet Textarbeit und gemeinsame Prüfungen. Vertrauliche Lesebereiche liegen außerhalb dieses gemeinsamen Bestands.',volumes:'Band- und Paketrepos erhalten klar bezeichnete lokale Freigaben; gemeinsame Register und Modellversionen werden repoübergreifend verbunden.'}[s.repos];
const data={hybrid:'TEI und Skripte liegen in Git, das gemeinsame Register in der Registerdatenbank. Freigegebene Snapshots verbinden beide.',git:'TEI, Regeln und Registerdateien werden in Git gepflegt; Abfrage- und Ausgabedatenbanken werden daraus abgeleitet.',db:'Die Editionsdatenbank ist der maßgebliche Pflegeort. Git hält Code, Schema und definierte Exporte; die Datenbank hat eigene Audit- und Sicherungsregeln.'}[s.data];
return [
`Die Albrecht-Edition verbindet ${organisation} mit langfristig verantworteter Datenpflege. ${host} Die Infrastruktur trägt wissenschaftliche Zusammenarbeit, Begutachtung und die abgestimmte Buch- und Digitalpublikation.`,
`${repo} ${data} Geprüfte Datenpakete werden mit Herkunftsmanifest integriert. Die vollständigen Arbeitsgeschichten bleiben in geschützten Herkunftsbeständen. Das öffentliche Repository entsteht aus freigegebenen Daten und führt eine eigene Publikationsgeschichte.`,
`Verbindliche Praxis, verständliche Einführung und verlässliche Zuständigkeit gehören zur Infrastruktur. Das gemeinsame Git-Handbuch wird halbjährlich und anlassbezogen geprüft. Die Mitarbeitervereinbarung regelt Beiträge, Nutzungsrechte und den Schutz der Arbeitsgeschichte. Git-Kennungen dokumentieren technische Bearbeitung; wissenschaftliche Verantwortung bleibt namentlich in TEI und Beitragsnachweisen ausgewiesen.`,
`Die Edition bewahrt zitierfähige Ergebnisse und die geschützte Entstehungsgeschichte als unterschiedliche Gegenstände. Das wissenschaftliche Archiv verantwortet Übernahme und geregelte Forschungszugänge. Daten, Schemata, Register, Verfahren und Handbuchfassungen bleiben verbunden; ein vollständiger Neuaufbau wird jährlich erprobt. Exporte und nachvollziehbare Schnittstellen ermöglichen einen Träger- oder Werkzeugwechsel.`,
`Versionierte Verfahren und Tests machen die Edition lernfähig. OCR- und LLM-Verfahren werden kontrolliert erprobt; editorisch relevante Übernahmen bleiben fachlich verantwortet. Prozessanalysen untersuchen vereinbarte Fragen zu Übergaben und Engpässen. Individuelle Leistungsrankings und Arbeitszeitprofile sind ausgeschlossen. Der Antrag umfasst Betrieb, Einführung, Regelpflege, Review, Rechteberatung, Migration und Archivleistungen als laufende Aufgaben.`
];}
export function proposalSections(s,r,label){return [
['1. Wissenschaftlicher Bedarf und Entscheidungsrechte',label('org',s.org)+'. '+r.organisation+' Die Bandredaktionen verantworten Lesarten und Kommentare. Die Editionskommission entscheidet über gemeinsame Prinzipien und Modelländerungen. Technische Schreibrechte ersetzen kein wissenschaftliches Mandat. Gutachtende brauchen einen lesbaren Prüfstand und eine nachvollziehbare Antwort auf ihre Einwände.'],
['2. Betrieb und geprüfte Alternativen',label('host',s.host)+'. '+r.host+' Im Referenzweg verantwortet der gemeinsame Akademieträger Zugänge, Betrieb und Übergabe. Die Universität bietet vorhandene Beratung, ein externer Dienst technische Bereitstellung; beide Alternativen werden an Partnerzugang, Leistung, Kostenentwicklung und Ausstieg geprüft.'],
['3. Datenzuständigkeit und Integration',label('repos',s.repos)+'. '+r.repos+' '+r.architecture+' '+r.stack+' Quellrepo, Quellcommit, Register-Snapshot, Regelversion und Abnahme werden im Importmanifest dokumentiert. Die Herkunft bleibt intern prüfbar, ohne die private Geschichte in die Publikation zu kopieren.'],
['4. Verlagsproduktion und öffentliche Freigabe',r.publication+' Verlagsdatenpaket, Digitalisate, Kommentar und Verlags-PDF haben getrennte Rechtevermerke. Die Rechte-/Publikationsstelle dokumentiert Gegenstand und Bedingungen; der Verlag erhält den abgestimmten Produktionsstand. Die öffentliche Umgebung übernimmt ausschließlich freigegebene Daten und eine eigene Geschichte. Historische Artefakte und Metadaten gehören zur Freigabeprüfung.'],
['5. Menschen und verbindliche Projektpraxis','Samir und seine Vertretung pflegen Handbuch, Profile und technische Prüfungen; die Fachredaktionen geben fachliche Regeln frei. Eva sichert Einführung, Pflegezeit und Bekanntgabe. Persönliche pseudonyme Git-Kennungen werden getrennt verwaltet. Wissenschaftliche Namen bleiben in TEI und Beitragsnachweisen sichtbar. Das Beteiligungs- und Zugangsverzeichnis erfasst auch Dienstleister, Verlag, IT und Gutachtende. Einstieg und Rollenwechsel werden anhand passender Vereinbarungen und Aufgaben freigegeben. Mitarbeitervereinbarung, Rechteanlage und Datenschutzinformation bilden den Rahmen; das Handbuch regelt die tägliche Umsetzung.'],
['6. Lernende Verfahren und Altdaten',r.model+' Neue Schnittstellen, OCR- und LLM-Verfahren werden mit repräsentativen Fällen, fachlicher Prüfung und Rücknahmeweg erprobt. Die Regeländerung erhält Test, Handbuchfassung und dokumentierten Geltungsbereich. Altdaten werden in bezeichneten Aufträgen nachgezogen; alte Regelversionen bleiben verständlich.'],
['7. Begutachtung und Produktionsqualität',r.review+' Das Handbuch ordnet Regelversion und Prüfstand zu. Rückmeldungen liegen im geschützten Reviewbereich. Korrekturen aus dem Satz kehren in den maßgeblichen Bestand zurück. Abhängige Register- und Webausgaben werden gemeinsam neu abgeleitet und geprüft. Die Rückimportprüfung H06 ist dafür ein konkretes Beispiel.'],
['8. Ergebnisse und Prozessgeschichte bewahren',r.archive+' Der Akademienverbund übergibt Publikations- und Prozesspakete getrennt an sein wissenschaftliches Archiv. Die Arbeitsgeschichte ist selbst wissenschaftlich bewahrungswürdig. Ein späterer Forschungszugang wird nach Antrag, Zweck- und Schutzprüfung entschieden; das Projektende öffnet die Bestände nicht automatisch.'],
['9. Offenheit und Unabhängigkeit','Ergebnisoffenheit betrifft freigegebene Editionsdaten, Methodenoffenheit dokumentierte Modelle und Verfahren. Prozesstransparenz wird durch Bewahrung und geregelten Forschungszugang ermöglicht. Dokumentierte TEI-/Registerexporte, verfügbare Transformationen und Wiederaufbauanleitungen ermöglichen einen Systemwechsel. Weder Open Source noch ein Exportanspruch allein belegen einen funktionierenden Ersatzbetrieb.'],
['10. Prozesssteuerung und Grenzen',r.analysis+' Die Mitarbeitervereinbarung und ein konkretes Analyseblatt begrenzen Frage, Daten, Zugriff und Bericht. Kennzahlen werden mit dem Team fachlich entwickelt. Individuelle Rankings und rekonstruierte Arbeitszeiten sind ausgeschlossen. Neue Zwecke, Dienste und tiefere Auswertungen werden vor ihrem Einsatz erneut geklärt.'],
['11. Ressourcen und institutionelle Zusagen','Der Antrag enthält dauerhaft finanzierte Arbeit für wissenschaftlich-technische Redaktion samt Vertretung, fachliche Abnahme, Schulung, Profil-/Regelpflege, IT-Betrieb, Rechteberatung, Migration und Archivübernahme. Eva legt dem Akademienverbund dafür den Stellen-, Leistungs- und Finanzierungsplan vor. Vor Bindung werden Umfang, Laufzeit und zuständige Träger in diesem Plan beschlossen.'],
['12. Nachweise und Revision','Ein Testkorpus mit Ausgabeprobe, ein vollständiger Bandaufbau, die Rollen-/Rechtematrix, ein geprüftes Publikationspaket und die Archivübernahmebeschreibung begleiten den Antrag. Der Verbund prüft die Strategie jährlich sowie bei Modell-, Träger- und Rechteänderungen. Neue Analysezwecke benötigen zusätzlich das vorgesehene Beteiligungsverfahren.']
];}
export function proposalDecisions(s){return [
['Betrieb','Verantworteter Betrieb und Ersatzweg','Trägerzusage, Serviceumfang, Partnerzugänge und Kostenplan','Eva / Infrastrukturträger','Vor Bindung beschließen'],
['Daten und Integration','Maßgeblicher Ort je Datenart','Testkorpus, Importmanifest, Register-Snapshot','Samir / Fachredaktionen','Mit Ausgabeprobe belegen'],
['Projektpraxis','Handbuch 1.1 und Einführung','Freigabe, Rollenmatrix, Profiltest und nächste Prüfung','Nora / Samir / Eva','Verbindliche Arbeitsregel'],
['Beiträge und Schutz','Mitarbeitervereinbarung und Anlagen','Rechte-/Datenschutzinformation; geregelte Analyse','Gesamtkoordination / zuständige Stellen','Vor Zugang erläutern'],
['Publikation','Eigene öffentliche Geschichte','Geprüftes Paket, Gegenstandsrechte, Verlagsabstimmung','Rechte-/Publikationsstelle / Bandredaktion','Freigabestatus: '+({approved:'Paket freigegeben',embargo:'Embargo',unknown:'noch ungeklärt'}[s.rights])],
['Bewahrung','Publikations- und Prozesspakete getrennt','Übernahme, Zugangskriterien und getesteter Wiederaufbau','Wissenschaftliches Archiv / IT','Wiederaufbau: '+({complete:'geprüft',missing:'Register-Snapshot fehlt',unknown:'noch ungeprüft'}[s.archive])]
];}
